import {isPico,encodeBytes} from './unified-project.js';
import {boardKey} from './board-hardware.js';
import {nativeSDKImage} from './pico-sdk-image.js';
import {sourceKey} from './source-files.js';
import {getSDKConnection,connectSDK,disconnectSDK} from './pico-sdk-bridge.js';
export function installPicoSDK({getProject,showDialog,adopt,onError,onSettingsChange}){
 const button=document.createElement('button');button.textContent='Pico SDK / CMake';button.hidden=true;document.querySelector('.menubar nav').append(button);
 let pending=null;
 button.onclick=()=>{const p=getProject(),eligible=isPico(p)&&p.language==='c';showDialog('Pico SDK / CMake','<p>Resmi SDK seçiliyken <strong>Derle</strong>, kaynakları bu bilgisayardaki yardımcıya gönderir. Gerçek CMake / Arm GNU çıktısı terminale gelir; firmware otomatik simülasyona yüklenir. <strong>Çalıştır</strong> ile başlatabilirsiniz.</p><form id="sdk-settings"><label>Derleme yöntemi<select id="sdk-engine"><option value="browser">Tarayıcı · hızlı SDK alt kümesi</option><option value="sdk-local">Resmi Pico SDK · bu bilgisayarda</option></select></label><label>CMake hedefi (tek hedef varsa boş bırakın)<input id="sdk-target" maxlength="80" placeholder="app"></label><button>Projeye uygula</button></form><h3>Bilgisayar bağlantısı</h3><p>Yardımcı açık kalmalı. Tarayıcı yerel bağlantı izni isteyebilir. Bağlantı dosyası yalnız bilgisayardaki yardımcıya erişmek içindir; proje JSON’una kaydedilmez.</p><label>Bağlantı dosyası seç<input id="sdk-connection-file" type="file" accept=".json"></label><details><summary>Bağlantı koduyla bağlan</summary><label>Port<input id="sdk-port" type="number" min="1" max="65535" value="18765"></label><label>Bağlantı kodu<input id="sdk-token" type="password" autocomplete="off" maxlength="100"></label></details><button id="sdk-connect">Yardımcıya bağlan</button> <button id="sdk-check">Bağlantıyı kontrol et</button> <button id="sdk-disconnect">Bağlantıyı kes</button><p id="sdk-connection-status" role="status"></p><h3>İlk kurulum</h3><p><a href="./wirevo-sdk-helper.zip" download>SDK yardımcısını indir</a>. Paketi açıp wirevo-sdk.cmd dosyasını başlatın. Resmi Pico SDK, Arm GNU, CMake ve Ninja yolları ilk kurulumda sorulur. Yardımcı, Derle’ye bastığınızda projenizin CMake komutlarını sizin hesabınızla çalıştırır; kendi güvendiğiniz projelerinizle kullanın.</p><p><a href="./notices/PICO-SDK-BRIDGE.md" target="_blank">Kurulum ve kullanım</a> · <a href="./notices/PICO-BROWSER-CMAKE.md" target="_blank">Tarayıcı alt kümesi</a></p><details><summary>Manuel firmware aktarımı</summary><label>Resmi SDK UF2 yükle<input id="pico-sdk-uf2" type="file" accept=".uf2"></label><p id="pico-sdk-result"></p></details>');
 const $=id=>document.getElementById(id),status=$('sdk-connection-status'),current=getSDKConnection();
 $('sdk-engine').value=p.settings?.picoBuildEngine||'browser';$('sdk-target').value=p.settings?.picoSDKTarget||'';
 $('sdk-settings').querySelectorAll('input,select,button').forEach(e=>e.disabled=!eligible);
 const apply=(engine,target)=>{if(getProject()!==p)throw Error('Proje değişti.');if(!eligible)throw Error('SDK yöntemini bir Pico C projesinde seçebilirsiniz.');if(engine==='sdk-local'&&p.settings?.picoArchitecture==='riscv')throw Error('Yerel SDK bağlantısı ARM içindir; ARM Pico projesi seçin.');onSettingsChange(engine,target);};
 $('sdk-settings').onsubmit=e=>{e.preventDefault();try{apply($('sdk-engine').value,$('sdk-target').value.trim());status.textContent='Derleme yöntemi kaydedildi. Artık Derle düğmesini kullanabilirsiniz.';}catch(err){status.textContent=err.message;}};
 status.textContent=current?'Bu sekmede bağlantı kaydı var. Yardımcının açık olduğunu kontrol edebilirsiniz.':'Henüz bu sekmede SDK yardımcısına bağlanılmadı.';
 if(pending){$('sdk-port').value=pending.port;$('sdk-token').value=pending.token;status.textContent='Yardımcı bağlantısı hazır. Yardımcıya bağlan düğmesine basın.';}
 async function connect(raw){try{status.textContent='SDK yardımcısına bağlanılıyor…';await connectSDK(raw);pending=null;status.textContent='Resmi SDK yardımcısı bağlı. Derle düğmesi hazır.';if(eligible&&p.settings?.picoArchitecture!=='riscv'){apply('sdk-local',$('sdk-target').value.trim());$('sdk-engine').value='sdk-local';}}catch(err){status.textContent=err.message;}}
 $('sdk-connect').onclick=()=>connect({protocol:1,port:Number($('sdk-port').value),token:$('sdk-token').value.trim()});
 $('sdk-check').onclick=()=>{const c=getSDKConnection();if(c)connect(c);else status.textContent='Önce yardımcının bağlantı dosyasını seçin.';};
 $('sdk-disconnect').onclick=()=>{disconnectSDK();status.textContent='SDK bağlantısı bu sekmeden kaldırıldı.';};
 $('sdk-connection-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4096)throw Error('Bağlantı dosyası geçersiz.');await connect(JSON.parse(await file.text()));}catch(err){status.textContent=err.message;}e.target.value='';};
 $('pico-sdk-uf2').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('UF2 en fazla 1 MB olabilir.');const image=nativeSDKImage(new Uint8Array(await file.arrayBuffer()),boardKey(p));if(getProject()!==p)throw Error('Proje değişti.');const next=structuredClone(p);next.settings.picoArchitecture='arm';next.firmware={format:'pico-sdk-bin',board:boardKey(p),payload:encodeBytes(image),source:p.code,sourceKey:sourceKey(next),imported:true,flashBytes:image.length};adopt(next);}catch(err){$('pico-sdk-result').textContent=err.message;onError(err.message);}e.target.value='';};
 };
 queueMicrotask(()=>{if(!location.hash.startsWith('#wirevo-sdk='))return;try{const [port,token]=decodeURIComponent(location.hash.slice(12)).split(':');pending={protocol:1,port:Number(port),token};}catch{}history.replaceState(null,'',location.pathname+location.search);button.onclick();});
 return {render(){button.hidden=!isPico(getProject())||getProject().language!=='c';}};
}
